import{_ as a,H as o,f as i,i as s}from"./chunks/framework.BauLNg70.js";const m=JSON.parse('{"title":"Publicar tu mod","description":"","frontmatter":{},"headers":[],"relativePath":"publishing.md","filePath":"publishing.md"}'),l={name:"publishing.md"};function t(r,e,n,d,c,u){return o(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="publicar-tu-mod" tabindex="-1">Publicar tu mod <a class="header-anchor" href="#publicar-tu-mod" aria-label="Permalink to &quot;Publicar tu mod&quot;">​</a></h1><p>Cómo publicar un mod ya completo a Steam Workshop, mantener releases y optar a niveles de verificación.</p><hr><h2 id="antes-de-publicar-—-checklist" tabindex="-1">Antes de publicar — checklist <a class="header-anchor" href="#antes-de-publicar-—-checklist" aria-label="Permalink to &quot;Antes de publicar — checklist&quot;">​</a></h2><ul><li>[ ] Probado en sideload local con la versión actual del juego.</li><li>[ ] Probado al menos con 1 mod más activo simultáneamente (para detectar interacciones).</li><li>[ ] Probado tras restart del juego (state persistido correctamente).</li><li>[ ] Probado con/sin DLCs declarados en <code>requires.dlcs</code>.</li><li>[ ] <code>mod.json</code> válido (<code>pnpm exec mod-validator</code> o similar proporcionado por el SDK del estudio si existe).</li><li>[ ] Iconos / screenshots preparados (PNG, &lt;500KB cada uno).</li><li>[ ] <code>metadata.description</code> clara, sin typos.</li><li>[ ] Changelog escrito (si es update de versión anterior).</li><li>[ ] License declarada (MIT, GPL, custom...).</li></ul><hr><h2 id="steam-workshop-—-proceso" tabindex="-1">Steam Workshop — proceso <a class="header-anchor" href="#steam-workshop-—-proceso" aria-label="Permalink to &quot;Steam Workshop — proceso&quot;">​</a></h2><h3 id="_1-empaquetar" tabindex="-1">1. Empaquetar <a class="header-anchor" href="#_1-empaquetar" aria-label="Permalink to &quot;1. Empaquetar&quot;">​</a></h3><p>Crea un <code>.zip</code> con la estructura:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-mod.zip</span></span>
<span class="line"><span>├── mod.json</span></span>
<span class="line"><span>├── dist/</span></span>
<span class="line"><span>│   └── mod.js</span></span>
<span class="line"><span>├── assets/</span></span>
<span class="line"><span>│   ├── icon.png</span></span>
<span class="line"><span>│   └── screenshots/</span></span>
<span class="line"><span>└── locales/</span></span></code></pre></div><p>Tamaño máximo recomendado: 5 MB. Workshop acepta más pero el download lento penaliza.</p><h3 id="_2-steam-workshop-client" tabindex="-1">2. Steam Workshop client <a class="header-anchor" href="#_2-steam-workshop-client" aria-label="Permalink to &quot;2. Steam Workshop client&quot;">​</a></h3><p>Desde Steam, abre el juego (Snake Classic o equivalente) → menú → Workshop → &quot;Create New Item&quot;. Sube el <code>.zip</code>.</p><p>Campos:</p><ul><li><strong>Title</strong>: <code>metadata.name</code> por defecto.</li><li><strong>Description</strong>: pega un README con secciones (qué hace, capturas, changelog).</li><li><strong>Visibility</strong>: public / friends only / unlisted.</li><li><strong>Tags</strong>: usa los del catálogo del juego (el estudio define).</li></ul><h3 id="_3-submit" tabindex="-1">3. Submit <a class="header-anchor" href="#_3-submit" aria-label="Permalink to &quot;3. Submit&quot;">​</a></h3><p>Tras subida exitosa, el Workshop ID es generado. <strong>Guárdalo</strong> — luego te servirá para updates.</p><h3 id="_4-verificacion-opcional" tabindex="-1">4. Verificación (opcional) <a class="header-anchor" href="#_4-verificacion-opcional" aria-label="Permalink to &quot;4. Verificación (opcional)&quot;">​</a></h3><p>El estudio puede ofrecer un flow de &quot;verificación&quot; de modders:</p><ul><li>Aplica via formulario.</li><li>Pasas test de detección de malware en tu mod.</li><li>Aceptas TOS específicos.</li><li>Recibes una clave de firma o flag que sube tu trust tier a <code>workshopVerified</code>.</li></ul><p>Mods verificados:</p><ul><li>Sin prompt al jugador en su activación.</li><li>Permisos estándar otorgados sin extra confirmación.</li><li>Banner &quot;Verified&quot; visible en Workshop y en settings del juego.</li></ul><hr><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h2><p>Para publicar una versión nueva:</p><ol><li>Bumpea <code>version</code> en <code>mod.json</code> (PATCH / MINOR / MAJOR según cambios).</li><li>Empaqueta el nuevo <code>.zip</code>.</li><li>En Steam Workshop, abre tu item existente → &quot;Update Item&quot; → sube el nuevo zip.</li><li>Añade entrada al changelog.</li></ol><p>Update automático para jugadores:</p><ul><li>Si publicaron <code>1.0.0</code>, instalan <code>1.1.0</code> (MINOR): sus settings se mantienen.</li><li>Si publican <code>2.0.0</code> (MAJOR): el cliente del jugador <strong>resetea settings</strong> del mod automáticamente al actualizar (avísalo en el changelog).</li></ul><hr><h2 id="sideload-distribution" tabindex="-1">Sideload distribution <a class="header-anchor" href="#sideload-distribution" aria-label="Permalink to &quot;Sideload distribution&quot;">​</a></h2><p>Si tu mod no va a Steam Workshop (private mod, beta cerrada, playtest):</p><ol><li>Distribuye el <code>.zip</code> por tus canales (GitHub releases, página web, Discord, etc.).</li><li>El jugador descomprime en <code>&lt;userData&gt;/&lt;gameId&gt;/mods/&lt;modId&gt;/</code>.</li><li>Reinicia el juego.</li></ol><p>Sideload mods son <code>unsigned</code> salvo que firmes con clave pública declarada (avanzado — ver firma manual con <code>ed25519</code> en <a href="https://github.com/leteo/my-game-fw/blob/main/docs/mods/security/signing-and-trust.md" target="_blank" rel="noreferrer">../security/signing-and-trust.md</a>).</p><hr><h2 id="versionado-y-compat" tabindex="-1">Versionado y compat <a class="header-anchor" href="#versionado-y-compat" aria-label="Permalink to &quot;Versionado y compat&quot;">​</a></h2><p>Cuando el juego anuncia una nueva versión MAJOR:</p><ul><li>Tu mod con <code>requires.hostApi: &#39;^1.0.0&#39;</code> queda <code>incompatible</code> con juego v2.x.</li><li>Probablemente necesites reescribir partes que dependían de la host API antigua. Consulta el <code>host-api-changelog</code>.</li><li>Publica <code>2.0.0</code> (MAJOR de tu mod) con <code>requires.hostApi: &#39;^2.0.0&#39;</code>.</li></ul><p>Los jugadores con la versión vieja del juego pueden seguir usando tu mod v1.x; los que actualizaron a v2.x descargan tu v2.0.0.</p><p>Workshop maneja la entrega de versiones compatibles automáticamente si declaraste los rangos correctamente.</p><hr><h2 id="si-tu-mod-entra-en-quarantine" tabindex="-1">Si tu mod entra en quarantine <a class="header-anchor" href="#si-tu-mod-entra-en-quarantine" aria-label="Permalink to &quot;Si tu mod entra en quarantine&quot;">​</a></h2><p>El framework marca mods que fallan repetidamente como <code>quarantined</code>. Los jugadores ven un mensaje &quot;Este mod falló — autor podría haber publicado una corrección&quot;. Tu trabajo:</p><ol><li>Reproduce el fault local con la última versión del juego.</li><li>Arregla.</li><li>Publica una versión nueva (PATCH bump).</li><li>Comunica en la página del Workshop: &quot;v1.2.4 arregla el crash de v1.2.3&quot;.</li></ol><p>Los jugadores des-quarantine-an manualmente desde settings tras actualizar. El framework no auto-des-quarantine.</p><hr><h2 id="si-recibes-reportes-de-seguridad" tabindex="-1">Si recibes reportes de seguridad <a class="header-anchor" href="#si-recibes-reportes-de-seguridad" aria-label="Permalink to &quot;Si recibes reportes de seguridad&quot;">​</a></h2><p>Si alguien reporta que tu mod podría tener un problema de seguridad (filtrar datos, hacer requests no declarados, etc.):</p><ol><li><strong>Toma en serio</strong> incluso si parece menor.</li><li>Audita tu código.</li><li>Publica un fix.</li><li>Comunica con transparencia en tu changelog.</li></ol><p>Si los reportes son válidos y graves, el estudio puede kill-switch tu mod remotamente (apagado en clientes sin update). Eso suele significar final de la relación con la plataforma.</p><hr><h2 id="resumen" tabindex="-1">Resumen <a class="header-anchor" href="#resumen" aria-label="Permalink to &quot;Resumen&quot;">​</a></h2><ul><li>Checklist exhaustivo antes de cada release.</li><li>Workshop process directo desde Steam client.</li><li>Verification flow opcional, sube tu trust tier.</li><li>SemVer estricto en updates.</li><li>Quarantine recoverable con fix.</li><li>Seguridad in incumplir → kill-switch terminal.</li></ul>`,52)])])}const h=a(l,[["render",t]]);export{m as __pageData,h as default};
